func baselineThinkTimeForClock(timeLeft, increment time.Duration, turnCount int) time.Duration {
	const baseReserve = 3 * time.Second
	const maxExtraReserve = 15 * time.Second // larger buffer once we reach the endgame
	const midgameStart = 10

	// Endgame begins ~35 ply, i.e. this side's ~17th move (TurnCount counts our
	// own moves). reserveRamp is the number of our moves over which the reserve
	// climbs from baseReserve to baseReserve+maxExtraReserve.
	const endgameStart = 17
	const reserveRamp = 13

	// Reserve ramps up through the endgame so we always keep a healthy buffer.
	reserve := baseReserve
	if turnCount > endgameStart {
		grown := time.Duration(turnCount-endgameStart) * (maxExtraReserve / reserveRamp)
		if grown > maxExtraReserve {
			grown = maxExtraReserve
		}
		reserve += grown
	}

	// Estimated moves remaining for THIS side. Low in the midgame (spend more of
	// the clock where it matters), then rising through the endgame so per-move
	// time shrinks aggressively and the growing reserve survives.
	var movesLeft time.Duration
	switch {
	case turnCount < midgameStart:
		movesLeft = 45
	case turnCount < endgameStart:
		movesLeft = 18
	case turnCount < 25:
		movesLeft = 28
	case turnCount < 35:
		movesLeft = 34
	default:
		movesLeft = 40
	}

	usable := timeLeft - reserve
	if usable < 0 {
		usable = 0
	}
	think := usable/movesLeft + increment
	// In long endgames we still want the larger reserve, but not at the cost of
	// blitzing critical queen/pawn positions while a minute remains. Spend a
	// controlled slice of clock above 45s; below that, keep the conservative
	// scramble behavior covered by TestThinkTimeForClockShrinksAndBuffersEndgame.
	if turnCount >= 35 && timeLeft > 45*time.Second {
		think += (timeLeft - 45*time.Second) / 15
	}
	if think < 50*time.Millisecond {
		think = 50 * time.Millisecond
	}
	maxThink := maxThinkTimeForClock(timeLeft)
	if turnCount >= midgameStart && turnCount < endgameStart && timeLeft > 60*time.Second {
		maxThink += maxThink / 4
	}
	if think > maxThink {
		think = maxThink
	}
	return think
}


func baselineThinkTimeForPosition(timeLeft, increment time.Duration, turnCount int, b *board.Board, side color.Color) time.Duration {
	think := baselineThinkTimeForClock(timeLeft, increment, turnCount)
	const criticalScrambleCutoff = 8 * time.Second
	if b == nil || !isCriticalSearchPosition(b, side) || timeLeft <= criticalScrambleCutoff {
		return think
	}
	minThink := 2500*time.Millisecond + increment
	criticalMax := maxThinkTimeForClock(timeLeft)
	if timeLeft > 60*time.Second {
		minThink = 5*time.Second + increment
		criticalMax *= 2
	} else if timeLeft < 20*time.Second {
		// Avoid a hard quality cliff when the clock crosses 20 seconds. Spend a
		// bounded tenth of the remaining clock on a critical position, preserving
		// enough time for the scramble while still allowing a real search.
		minThink = timeLeft/10 + increment
	}
	if think < minThink {
		think = minThink
	}
	if think > criticalMax {
		think = criticalMax
	}
	return think
}

func TestClockSafetyFreshGameComparison(t *testing.T) {
 data,err:=os.ReadFile("../../../testdata/lichess_2026_10_26_post_build_games.json");if err!=nil {t.Fatal(err)}
 var games []struct {
  ID,Moves string
  Players map[string]struct{User struct{ID string}}
  Clock struct{Initial,Increment int}
  Clocks []int
 }
 if err:=json.Unmarshal(data,&games);err!=nil {t.Fatal(err)}
 total,healthy:=0,0
 changed:=[]map[string]any{}
 for _,g:=range games {
  side:=color.Black;if g.Players["white"].User.ID=="vadbot" {side=color.White}
  replay,err:=analysis.ReplaySANMoves(g.Moves);if err!=nil {t.Fatal(err)}
  for _,r:=range replay {
   if r.SideToMove!=side {continue}
   clock:=time.Duration(g.Clock.Initial)*time.Second
   if r.Ply>=3 {clock=time.Duration(g.Clocks[r.Ply-3])*10*time.Millisecond}
   increment:=time.Duration(g.Clock.Increment)*time.Second
   parsed,err:=analysis.ParseFEN(r.FENBefore);if err!=nil {t.Fatal(err)}
   turn:=(r.Ply-1)/2
   old:=baselineThinkTimeForPosition(clock,increment,turn,parsed.Board,side)
   current:=thinkTimeForPosition(clock,increment,turn,parsed.Board,side)
   total++
   limit:=clock/2;if limit<time.Millisecond {limit=time.Millisecond}
   if current<=0 || current>limit {t.Fatalf("unsafe clock budget for %s ply %d: %s/%s",g.ID,r.Ply,current,clock)}
   if clock>=8*time.Second {
    healthy++
    if old!=current {t.Fatalf("healthy budget changed for %s ply %d: %s -> %s",g.ID,r.Ply,old,current)}
   }
   if old!=current {changed=append(changed,map[string]any{"gameId":g.ID,"ply":r.Ply,"clockMs":clock.Milliseconds(),"incrementMs":increment.Milliseconds(),"oldMs":old.Milliseconds(),"newMs":current.Milliseconds()})}
  }
 }
 result:=map[string]any{"games":len(games),"botTurns":total,"healthyClockTurnsUnchanged":healthy,"changedTurns":changed,"method":"Exact SAN/FEN and exported pre-move own clocks; compare production allocator against capped allocator with identical critical-position classification."}
 output,_:=json.MarshalIndent(result,"","  ")
 if err:=os.WriteFile("/tmp/chess-oct26-clock-corpus-comparison.json",append(output,'\n'),0600);err!=nil {t.Fatal(err)}
 fmt.Printf("Clock replay: %d games, %d bot turns, %d healthy unchanged, %d low-clock changes\n",len(games),total,healthy,len(changed))
}
